import csv

# Read the CSV file and create a lookup by CDSCode
cds_to_district_type = {}
cds_to_charter_funding = {}
cds_to_charter_school = {}
with open('csv/frpm.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        cds = row['CDSCode']
        if cds not in cds_to_district_type:
            cds_to_district_type[cds] = row['District Type']
            cds_to_charter_funding[cds] = row['Charter Funding Type']
            cds_to_charter_school[cds] = row['Charter School (Y/N)']

# Schools from satscores with AvgScrMath > 400 and Riverside districts
schools = [
    ('33103300000000', None, 'Riverside County Office of Education'),
    ('33103300110833', 'River Springs Charter', 'Riverside County Office of Education'),
    ('33672150000000', None, 'Riverside Unified'),
    ('33672153330024', 'Arlington High', 'Riverside Unified'),
    ('33672153330859', 'Martin Luther King Jr. High', 'Riverside Unified'),
    ('33672153334406', 'John W. North High', 'Riverside Unified'),
    ('33672153336237', 'Polytechnic High', 'Riverside Unified'),
    ('33672153336492', 'Ramona High', 'Riverside Unified'),
]

print("School Name | Funding Type")
for cds, sname, dname in schools:
    school_name = sname if sname else 'N/A'

    if cds in cds_to_district_type:
        is_charter = cds_to_charter_school.get(cds, '0')

        if is_charter == '1':
            # For charter schools, use Charter Funding Type
            funding = cds_to_charter_funding.get(cds, '')
            if funding == '':
                funding = 'Not in CS funding model'
        else:
            # For non-charter schools, use District Type as funding type
            funding = cds_to_district_type.get(cds, 'N/A')
    else:
        funding = 'Not found in CSV'

    print(f"{school_name} | {funding}")

