import csv

# Read the CSV file and create a lookup by District Name
district_to_funding = {}
with open('csv/frpm.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        district_name = row['District Name']
        charter_funding = row['Charter Funding Type']
        district_type = row['District Type']

        if district_name not in district_to_funding:
            district_to_funding[district_name] = {
                'charter_funding': charter_funding,
                'district_type': district_type
            }

# Check Riverside districts
riverside_districts = ['Riverside County Office of Education', 'Riverside Unified']
for dname in riverside_districts:
    if dname in district_to_funding:
        print(f"{dname}: {district_to_funding[dname]}")
    else:
        print(f"{dname}: Not found")

